package com.bank.shard.routing;

import org.springframework.stereotype.Component;

@Component
public class ShardRouter {
    private final int shardCount = 3;

    // Consistent hashing keeps related rows together and spreads load evenly.
    // account_id (not a monotonic sequence) avoids hot spots on the newest shard.
    public int shardFor(String accountId) {
        int hash = Math.abs(accountId.hashCode());
        return hash % shardCount;
    }

    public int shardCount() { return shardCount; }
}
