package com.bank.shard.service;

import com.bank.shard.routing.ShardRouter;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;

@Service
public class ShardedAccountService {
    private static final Logger log = LoggerFactory.getLogger(ShardedAccountService.class);
    private final ShardRouter router;
    private final List<JdbcTemplate> shards;   // one JdbcTemplate per shard node

    public ShardedAccountService(ShardRouter router, List<JdbcTemplate> shards) {
        this.router = router; this.shards = shards;
    }

    // Single-shard read: route by account_id so the common query touches ONE shard.
    public BigDecimal balanceOf(String accountId) {
        int shard = router.shardFor(accountId);
        BigDecimal bal = shards.get(shard).queryForObject(
            "SELECT balance FROM accounts WHERE account_id = ?", BigDecimal.class, accountId);
        log.info("Read balance of {} from shard {}", accountId, shard);
        return bal;
    }

    // Single-shard write
    public void credit(String accountId, BigDecimal amount) {
        int shard = router.shardFor(accountId);
        shards.get(shard).update(
            "UPDATE accounts SET balance = balance + ? WHERE account_id = ?", amount, accountId);
        log.info("Credited {} to {} on shard {}", amount, accountId, shard);
    }
}
