package com.bank.shard.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;

@Service
public class CrossShardReportService {
    private static final Logger log = LoggerFactory.getLogger(CrossShardReportService.class);
    private final List<JdbcTemplate> shards;

    public CrossShardReportService(List<JdbcTemplate> shards) { this.shards = shards; }

    // Cross-shard query: fan out to EVERY shard, compute partials, merge.
    // This is the expensive operation sharding introduces — kept rare, offloaded to reporting.
    public BigDecimal totalBankBalance() {
        BigDecimal total = BigDecimal.ZERO;
        for (int i = 0; i < shards.size(); i++) {
            BigDecimal partial = shards.get(i).queryForObject(
                "SELECT COALESCE(SUM(balance),0) FROM accounts", BigDecimal.class);
            log.info("Shard {} partial total = {}", i, partial);
            total = total.add(partial);   // coordinator merges partials
        }
        log.info("Cross-shard total bank balance = {}", total);
        return total;
    }
}
